const r = await Promise.all([
  gm.run_shell({ command: "cd /workspace/cleetus && grep -n -i 'release\\|git.jayzee.co\\|ls-remote\\|upstream\\|commit subject' docs/OPEN-ITEMS.md | cut -c1-260; echo '== OPEN-023 block'; grep -n '^### OPEN-02[2-4]' docs/OPEN-ITEMS.md" }),
  gm.run_shell({ command: "cd /workspace/cleetus && grep -rn -i 'ls-remote\\|release-commit\\|release commit\\|commit subject' --exclude-dir=node_modules --exclude-dir=.git --exclude-dir=runs --exclude-dir=kernel --exclude-dir=site --exclude-dir=sources docs scripts .jayzee/reference/COVERAGE.md .jayzee/update-engine-pin.py .jayzee/reference/engine-deep 2>/dev/null | cut -c1-240 | head -30; echo '(end)'" }),
]);
return r.map(x => x.output);

const oldS = "The engine.yaml sha256 field stays the release pin b5d10e377d047b1f2d5d303009fe45757aad4abb66fa9ab2a32951676d93b630, which update-engine-pin.py reads, and the api-reference hash is recorded under api_reference_sha256 in engine.yaml and the engine INDEX.";
const newS = "The engine.yaml sha256 field stays the release pin b5d10e377d047b1f2d5d303009fe45757aad4abb66fa9ab2a32951676d93b630, which update-engine-pin.py reads. That value is recorded as a reference value and is not verified against an upstream: the release-commit check is out of scope, not open, because cleetus's work is published only to AnEntrypoint/cleetus (this repo's origin) and jayzee's upstream (git.jayzee.co) is not a publication target. No credentials are requested for it. The api-reference hash is recorded under api_reference_sha256 in engine.yaml and the engine INDEX.";
const r = await gm.edit_file({ path: "/workspace/cleetus/docs/OPEN-ITEMS.md", old: oldS, new: newS, replaceAll: false });
const v = await gm.run_shell({ command: "cd /workspace/cleetus && grep -c 'out of scope, not open' docs/OPEN-ITEMS.md && node scripts/check-open-items.mjs; echo EXIT=$?" });
return [r, v.output];

const a = await gm.git_add({ paths: ["docs/OPEN-ITEMS.md"] });
const c = await gm.git_commit({ message: "Close the release-commit check as out of scope in OPEN-023", paths: ["docs/OPEN-ITEMS.md"], author: "lanmower" });
const s = await gm.run_shell({ command: "cd /workspace/cleetus && git log -1 --format='%H%n%an <%ae>%n%B' && git status --short && echo CLEAN_CHECK_DONE" });
return [a, c, s.output];

const b = await gm.run_shell({ command: "cd /workspace/cleetus && npm run build 2>&1 | tail -n 15; echo BUILD_EXIT=${PIPESTATUS[0]}" });
const k = await gm.run_shell({ command: "cd /workspace/cleetus && npm run check 2>&1 | tail -n 40; echo CHECK_EXIT=${PIPESTATUS[0]}" });
const o = await gm.run_shell({ command: "cd /workspace/cleetus && node scripts/check-open-items.mjs 2>&1; echo OPEN_EXIT=$?" });
return [b.output, k.output, o.output];

const p = await gm.git_push({});
const l = await gm.run_shell({ command: "cd /workspace/cleetus && git fetch origin main -q && git log origin/main -1 --format='%H %s' && git status -sb | head -n 2" });
return [p, l.output];
